-- 013_migrate_notion_lessons.sql
-- Migracja treści lekcji z Notion do Supabase
-- Wygenerowano: 2026-04-07

DO $$
DECLARE
  v_path_wspolna uuid;
  v_path_nocode uuid;
  v_path_kod uuid;
  v_course_wspolna uuid;
  v_course_nocode uuid;
  v_course_kod uuid;
  v_lesson_id uuid;
BEGIN

SELECT id INTO v_path_wspolna FROM public.paths WHERE slug = 'wspolna';
SELECT id INTO v_path_nocode FROM public.paths WHERE slug = 'no_code';
SELECT id INTO v_path_kod FROM public.paths WHERE slug = 'kod';

DELETE FROM public.courses WHERE path_id IN (v_path_wspolna, v_path_nocode, v_path_kod);

VALUES (v_path_wspolna, 'Kurs AI – Ścieżka Wspólna', 1)
RETURNING id INTO v_course_wspolna;

VALUES (v_path_nocode, 'Kurs AI – Ścieżka No-Code', 1)
RETURNING id INTO v_course_nocode;

VALUES (v_path_kod, 'Kurs AI – Ścieżka B – Kod', 1)
RETURNING id INTO v_course_kod;

-- ============================================================
-- ŚCIEŻKA WSPÓLNA (mode=''single'')
-- ============================================================

-- Lesson 1: Wstęp
VALUES (v_course_wspolna, 'Wstęp', 1, '8 min')
RETURNING id INTO v_lesson_id;


-- Lesson 2: Sztuka i inżynieria Promptowania
VALUES (v_course_wspolna, 'Sztuka i inżynieria Promptowania', 2, '15 min')
RETURNING id INTO v_lesson_id;


-- Lesson 3: Twój nowy zespół – modele webowe
VALUES (v_course_wspolna, 'Twój nowy zespół – modele webowe', 3, '12 min')
RETURNING id INTO v_lesson_id;


-- Lesson 4: Baza narzędzi
VALUES (v_course_wspolna, 'Baza narzędzi', 4, '10 min')
RETURNING id INTO v_lesson_id;


-- ============================================================
-- ŚCIEŻKA NO-CODE (mode=''technical'')
-- ============================================================

-- Lesson 1: Zarządzanie wiedzą (pliki .md)
VALUES (v_course_nocode, 'Zarządzanie wiedzą (pliki .md)', 1, '10 min')
RETURNING id INTO v_lesson_id;


-- Lesson 2: Systemy agentowe bez kodu
VALUES (v_course_nocode, 'Systemy agentowe bez kodu', 2, '12 min')
RETURNING id INTO v_lesson_id;


-- Lesson 3: AI w Social Media i Content Automation
VALUES (v_course_nocode, 'AI w Social Media i Content Automation', 3, '10 min')
RETURNING id INTO v_lesson_id;


-- Lesson 4: Twój osobisty analityk danych (AI Data Agent)
VALUES (v_course_nocode, 'Twój osobisty analityk danych (AI Data Agent)', 4, '12 min')
RETURNING id INTO v_lesson_id;


-- ============================================================
-- ŚCIEŻKA KOD (mode=''technical'')
-- ============================================================

-- Lesson 1: Claude Code IDE w praktyce
VALUES (v_course_kod, 'Claude Code IDE w praktyce', 1, '15 min')
RETURNING id INTO v_lesson_id;


-- Lesson 2: Inżynieria systemów AI
VALUES (v_course_kod, 'Inżynieria systemów AI', 2, '15 min')
RETURNING id INTO v_lesson_id;


-- Lesson 3: Najlepsze TechStacki w praktyce
VALUES (v_course_kod, 'Najlepsze TechStacki w praktyce', 3, '12 min')
RETURNING id INTO v_lesson_id;


-- Lesson 4: Zaawansowani agenci (Multi-Agent Networks)
VALUES (v_course_kod, 'Zaawansowani agenci (Multi-Agent Networks)', 4, '18 min')
RETURNING id INTO v_lesson_id;


-- Lesson 5: DevOps w AI
VALUES (v_course_kod, 'DevOps w AI', 5, '12 min')
RETURNING id INTO v_lesson_id;


END $$;
